  ('machu-picchu-peru', '10S', 'Machu Picchu', 'Peru', 'A lost city in the clouds', 'live', 'verified', 'mountainValley', 'Cusco, Sacred Valley & Machu Picchu', '{"expedition","romance","culture"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["Machu Picchu citadel sits at 2,430 m; Cusco gateway at ~3,400 m — altitude, not crime, is the headline planning constraint.","Entry is by timed circuit ticket only (no free roaming); daily cap 4,500 standard / 5,600 high season (Jun 19–Nov 2).","Classic Inca Trail is guided-mandatory, capped at 500 permits/day (~200 hikers), sells out 4–7 months ahead, and closes every February.","Cusco / Sacred Valley / Inca Trail / Machu Picchu are State-Dept-named as NOT in any higher-risk advisory area — the strongest clean-zone in South America.","Rail from Ollantaytambo (~1h45m) via PeruRail/Inca Rail; the Belmond Hiram Bingham is the luxury tier and bundles citadel entry, bus and guide."],"safety":{"emergency":"105","emergency_ambulance":"117","tourist_line":"iPerú / Policía de Turismo","hospital":"Cusco private clinics for routine + altitude care; serious cases evac to Lima (Clínica Anglo Americana / Ricardo Palma); Aguas Calientes + trail remote","book_enabled":true,"air_access_verified":true,"air_access_note":"Cusco (CUZ) via Lima (LIM); then rail Ollantaytambo → Aguas Calientes; shuttle bus to the gate","altitude_m":{"cusco":3400,"citadel":2430,"sacred_valley_base":2800,"dead_womans_pass":4215,"salkantay_pass":4650,"rainbow_mountain":5000},"altitude_note":"Acute mountain sickness (soroche) is the primary health risk; acclimatize in the lower Sacred Valley first, ascend gradually, coca tea","water":"bottled/purified only","malaria":"none at altitude (Cusco/Sacred Valley/Machu Picchu); malaria risk is in the low-elevation Amazon","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/peru","read":"2026-08-20T14:53:51Z","page_updated":"2026-06-22T23:35:12+01:00","source_country":"peru","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"fcdo_zones":[{"name":"The VRAEM (Apurimac, Ene and Mantaro valley)","lvl":4},{"name":"The Colombia-border area of Loreto","lvl":4}]},"timing":{"peak":"June–August (dry season; Jun–Jul apex; citadel cap 5,600 Jun 19–Nov 2)","inflection_curve_start":"early December (prior year); tickets release ~Nov 17","fire_date":"2026-11-24","shoulder":"April–May & September–October","green":"November–March (lush/wet; February = Inca Trail closed)","booking_lead":"Inca Trail 4–7 months for peak (6–7 Jun–Jul); citadel timed tickets weeks–months; marquee hotels + Hiram Bingham as early as the permit","event_peaks":["Inti Raymi — Festival of the Sun, Cusco, June 24"],"off_season_specials":"Nov–Mar green-season Salkantay/Lares + Vistadome rail packages"},"jewels":[{"name":"Dawn entry via the Sun Gate (Inti Punku)","si_tag":"GEA","status":"live","hook":"Inca Trail finishers walk in at first light — the most cinematic arrival at the citadel","bookable_category":"guided_trek_package","tier":"premier","source":"https://www.ticketmachupicchu.com/hiking-guide-sun-gate/","timing":"June–August","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Inca Trail finishers walk in at first light — the most cinematic arrival at the citadel","when":"June–August","commission":"direct-operator DMC via OutsideAgents/Fora","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture","expedition"],"shelf_fit":{"culture":"evidenced","expedition":"primary","romance":"destination"},"commission_lane":["operator","DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Huayna Picchu","si_tag":"GEA","status":"live","hook":"The iconic peak behind the postcard — straight-down views, 400 permits/day","bookable_category":"circuit_ticket_addon","tier":"comfort","source":"https://www.s