  ('cartagena-colombia', '10S', 'Cartagena & Colombia''s Caribbean Coast', 'Colombia', 'Walled colonial casas and Caribbean nights', 'live', 'verified', 'venice', 'Colombia''s Caribbean Coast', '{"romance","tropical","culture"}', '{"tropical"}', '{"essential","premier","luxury","ultra"}', null, null, '{"key_facts":["Cartagena''s Ciudad Amurallada (walled old city + fortifications) is the anchor; Castillo San Felipe is the largest Spanish fort in South America; most visitors need 3–4 days.","Islas del Rosario + Barú (Playa Blanca) — ~1hr speedboat to Corales del Rosario National Park, reef snorkel, beach lunch.","Getsemaní — best street art on the coast + Plaza de la Trinidad salsa nights, just outside the walls.","Santa Marta + Tayrona NP protect 150 km² where the Sierra Nevada meets the sea; Cabo San Juan is the iconic cove.","Barranquilla Carnival — UNESCO Intangible Heritage, largest carnival outside Brazil; 2026 dates 14–17 February."],"safety":{"emergency":"123","hospital":"Cartagena private hospitals (stabilization); serious cases route to Bogotá or US medical evacuation","book_enabled":true,"risk_codes":["C","T","U","K","N"],"risk_code_meanings":{"C":"Crime — violent crime (murder, assault, robbery), drugging (scopolamine), extortion, express kidnapping occur throughout Colombia incl. cities","T":"Terrorism — attacks possible with little/no warning; car bombs, grenades, IEDs, drones","U":"Unrest — demonstrations can shut roads and turn violent","K":"Kidnapping or Hostage-Taking — kidnapping-for-ransom reported","N":"Natural Disaster — volcano, earthquake, landslide"},"named_danger":["Arauca","Cauca excl Popayán","Valle del Cauca excl Cali","Norte de Santander","Venezuela border ~10km"],"cartagena_in_named_danger":false,"air_access_verified":"CTG (Rafael Núñez Intl) — direct international incl. Miami (AA, Avianca) and New York JFK (JetBlue year-round, Avianca seasonal)","water":"bottled","vaccinations":"yellow fever recommended for Tayrona/jungle/Sierra Nevada; dengue present on coast; check CDC","scopolamine_caution":"''devil''s breath''/burundanga drugging — colourless/tasteless; never accept drinks/food/tabs from strangers; dating-app method documented in Cartagena","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/colombia","read":"2026-08-20T14:47:41Z","page_updated":"2026-08-18T15:51:11+01:00","source_country":"colombia","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"fcdo_zones":[{"name":"all of Norte de Santander Department, including Cúcuta","lvl":3,"posture":"all-but-essential"},{"name":"all of Arauca Department","lvl":3,"posture":"all-but-essential"},{"name":"the municipality of Puerto Carreño in Vichada Department","lvl":3,"posture":"all-but-essential"},{"name":"within 5km of the rest of the border with Venezuela","lvl":3,"posture":"all-but-essential","note":"The FCDO separately advises against all travel to Venezuela''s side of the border — do not use any Colombia-Venezuela land crossing."},{"name":"Chocó Department","lvl":3,"posture":"all-but-essential","except":["the department capital Quibdó","the towns of Nuquí and Bahía Solano","Capurganá"]},{"name":"the western part of Valle del Cauca Department, including Buenaventura","lvl":3,"posture":"all-but-essential"},{"name":"the municipality of Jamundí, Valle del Cauca","lvl":3,"posture":"all-but-essential"},{"name":"the South Pacific, Sanquianga and Telembi regions of Nariño Department","lvl":3,"posture":"all-but-essential"},{"name":"the southern part of Córdoba Department","lvl":3,"posture":"all-but-essential"},{"name":"the Urabá and Bajo Cauca regions of Antioquia Department","lvl":3,"posture":"all-but-essential"},{"name":"the southern part of Bolívar Department","lvl":3,"posture":"all-but-essential"},{"name":"all of Guaviare Department","lvl":3,"posture":"all-but-essential","except":["the department capital San José del Guaviare"]},{"name":"Cartagena del Chairá, San Vicente del Caguan, Puerto Rico, El Doncello, Paujil and La Montañita in Caquetá Department","lvl":3,"posture":"all-but-essential"},{"name":"the Ariari region of southern Meta","lvl":3,"posture":"all-but-essential","except":["Caño Cristales"],"note":"If travelling to Caño Cristales, the FCDO advises travelling by air from the town of La Macarena with a reputable tour company."},{"name":"within 5km of the border with Ecuador","lvl":3,"posture":"all-but-essential","except":["the border crossing on the Pan-American highway at the Puente Internacional de Rumichaca","the city of Ipiales in Nariño Department"]},{"name":"all of Cauca Department","lvl":3,"posture":"all-but-essential","except":["the department capital Popayán"],"note":"The advisory page nests Cauca inside its Ecuador-border sentence; we hold it as a restricted department in its own right — the stricter of the two readings, consistent with the FCDO''s regional-risks detail."},{"name":"Orito, San Miguel, Valle del Guamuez, Puerto Caicedo, Puerto Guzmán, Puerto Asis and Puerto Leguizamo in Putumayo Department","lvl":3,"posture":"all-but-essential"}]},"timing":{"peak":"Dec–Mar/Apr (dry); true peak mid-Dec → mid/late-Jan","inflection_curve_start":"early December","fire_date":"mid-to-late November (peak); ~late-January (Barranquilla Carnival)","event_peaks":[{"event":"Barranquilla Carnival","dates_2026":"14–17 February","note":"UNESCO; largest carnival outside Brazil; Barranquilla rooms sell out/price hard"},{"event":"Independence Day (Cartagena)","dates":"November 11","note":"coastal rates +30–40% Nov 9–12"},{"event":"Christmas–New Year","dates":"Dec 20–31","note":"maximum annual congestion"}],"off_season_specials":"Aug–Nov (rates ~half of peak); Jul–Aug veranillo del Niño = best weather-to-cost"},"jewels":[{"name":"Walled Old City + rampart sunset (Café del Mar)","si_tag":"romance","tier":"premier","source":"https://www.lonelyplanet.com/articles/top-things-to-do-in-cartagena-colombia","timing":"De